test('addLine adds a new line to an invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  });
  assert.equal(invoice.ok, true);
  const r = addLine(invoice.value, { sku: 'LOGO-PACK', qty: 1 });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 2);
  assert.equal(r.value.lines[1].sku, 'LOGO-PACK');
  assert.equal(r.value.lines[1].name, 'Logo package');
  assert.equal(r.value.lines[1].qty, 1);
});

test('addLine increments qty if SKU already exists', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  });
  assert.equal(invoice.ok, true);
  const r = addLine(invoice.value, { sku: 'DES-HOUR', qty: 2 });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 1);
  assert.equal(r.value.lines[0].qty, 5);
  assert.equal(r.value.lines[0].name, 'Design work (hour)');
});

test('addLine enriches new lines with product data', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(invoice.ok, true);
  const r = addLine(invoice.value, { sku: 'ICON-SET', qty: 2 });
  assert.equal(r.ok, true);
  const line = r.value.lines.find((l) => l.sku === 'ICON-SET');
  assert.equal(line.name, 'Icon set (24 icons)');
  assert.equal(line.unitPrice, 980);
  assert.equal(line.vatRate, 21);
});

test('addLine validates qty is a positive integer', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(invoice.ok, true);
  const cases = [0, -1, 1.5, '5', null];
  for (const qty of cases) {
    const r = addLine(invoice.value, { sku: 'LOGO-PACK', qty });
    assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' }, `should reject qty=${qty}`);
  }
});

test('addLine rejects unknown SKU', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
