import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';

test('createInvoice creates a draft invoice with enriched lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
  assert.equal(r.value.issueDate, '2026-10-07');
  assert.equal(r.value.status, 'draft');
  assert.equal(r.value.lines.length, 1);
  assert.equal(r.value.lines[0].sku, 'DES-HOUR');
  assert.equal(r.value.lines[0].name, 'Design work (hour)');
  assert.equal(r.value.lines[0].qty, 5);
  assert.equal(r.value.lines[0].unitPrice, 8500);
  assert.equal(r.value.lines[0].vatRate, 21);
});

test('createInvoice enriches multiple lines', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 3 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 2);
  assert.equal(r.value.lines[0].name, 'Design work (hour)');
  assert.equal(r.value.lines[1].name, 'Logo package');
});

test('createInvoice rejects an unknown customer', () => {
  const r = createInvoice({
    customerId: 'C-999',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice validates date format', () => {
  const cases = [
    '2026-13-01', // invalid month
    '2026-02-30', // invalid day
    '2026-2-01', // missing leading zero
    'not-a-date',
    '2026/10/07',
    undefined,
  ];
  for (const issueDate of cases) {
    const r = createInvoice({
      customerId: 'C-001',
      issueDate,
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    });
    assert.deepEqual(r, { ok: false, error: 'DATE_INVALID' }, `should reject ${issueDate}`);
  }
});

test('createInvoice accepts valid dates', () => {
  const cases = ['2026-01-01', '2026-12-31', '2000-02-29'];
  for (const issueDate of cases) {
    const r = createInvoice({
      customerId: 'C-001',
      issueDate,
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    });
    assert.equal(r.ok, true, `should accept ${issueDate}`);
  }
});

test('createInvoice rejects an empty lines array', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [],
  });
  assert.deepEqual(r, { ok: false, error: 'NO_LINES' });
});

test('createInvoice rejects non-array lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: null,
  });
  assert.deepEqual(r, { ok: false, error: 'NO_LINES' });
});

test('createInvoice validates line quantities', () => {
  const cases = [
    { qty: 0 },
    { qty: -1 },
    { qty: 1.5 },
    { qty: '5' },
    { qty: null },
  ];
  for (const line of cases) {
    const r = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', ...line }],
    });
    assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' }, `should reject qty=${line.qty}`);
  }
});

test('createInvoice rejects unknown SKUs', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'NOPE', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice does not mutate input lines', () => {
  const input = [{ sku: 'DES-HOUR', qty: 1 }];
  createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: input,
  });
  assert.deepEqual(input, [{ sku: 'DES-HOUR', qty: 1 }]);
});

test('createInvoice returns a new object', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const r2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.notStrictEqual(r1.value, r2.value);
  assert.notStrictEqual(r1.value.lines, r2.value.lines);
});

test('lineTotal calculates qty × unitPrice', () => {
  const r = lineTotal({ qty: 5, unitPrice: 8500 });
  assert.equal(r.ok, true);
  assert.equal(r.value, 42500);
});

test('lineTotal handles various quantities and prices', () => {
  assert.equal(lineTotal({ qty: 1, unitPrice: 100 }).value, 100);
  assert.equal(lineTotal({ qty: 10, unitPrice: 1000 }).value, 10000);
  assert.equal(lineTotal({ qty: 3, unitPrice: 120000 }).value, 360000);
});

test('lineTotal validates qty is a positive integer', () => {
  const cases = [
    { qty: 0, error: 'QTY_INVALID' },
    { qty: -5, error: 'QTY_INVALID' },
    { qty: 1.5, error: 'QTY_INVALID' },
    { qty: '5', error: 'QTY_INVALID' },
    { qty: null, error: 'QTY_INVALID' },
  ];
  for (const c of cases) {
    const r = lineTotal({ qty: c.qty, unitPrice: 100 });
    assert.deepEqual(r, { ok: false, error: c.error }, `should reject qty=${c.qty}`);
  }
});

test('lineTotal validates unitPrice is a non-negative integer', () => {
  const cases = [
    { unitPrice: -100, error: 'AMOUNT_INVALID' },
    { unitPrice: 1.5, error: 'AMOUNT_INVALID' },
    { unitPrice: '100', error: 'AMOUNT_INVALID' },
    { unitPrice: null, error: 'AMOUNT_INVALID' },
  ];
  for (const c of cases) {
    const r = lineTotal({ qty: 1, unitPrice: c.unitPrice });
    assert.deepEqual(r, { ok: false, error: c.error }, `should reject unitPrice=${c.unitPrice}`);
  }
});

test('lineTotal accepts zero unitPrice', () => {
  const r = lineTotal({ qty: 5, unitPrice: 0 });
  assert.equal(r.ok, true);
  assert.equal(r.value, 0);
});

test('invoiceTotals calculates subtotal, discount and total', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 8500 },
      { qty: 1, unitPrice: 120000 },
    ],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 162500);
  assert.equal(r.value.discount, 0);
  assert.equal(r.value.total, 162500);
});

test('invoiceTotals sums multiple line totals', () => {
  const invoice = {
    lines: [
      { qty: 3, unitPrice: 100 },
      { qty: 2, unitPrice: 200 },
      { qty: 1, unitPrice: 500 },
    ],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 1200);
  assert.equal(r.value.discount, 0);
  assert.equal(r.value.total, 1200);
});

test('invoiceTotals returns an object with subtotal, discount and total', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 100 }],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.ok('subtotal' in r.value);
  assert.ok('discount' in r.value);
  assert.ok('total' in r.value);
});

test('invoiceTotals validates invoice has lines', () => {
  const cases = [null, {}, { lines: null }, { lines: [] }];
  for (const invoice of cases) {
    const r = invoiceTotals(invoice);
    assert.deepEqual(r, { ok: false, error: 'NO_LINES' });
  }
});

test('invoiceTotals propagates line validation errors', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 100 },
      { qty: 0, unitPrice: 100 },
    ],
  };
  const r = invoiceTotals(invoice);
  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('invoiceTotals works with real invoices from createInvoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  assert.equal(invoice.ok, true);
  const r = invoiceTotals(invoice.value);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 5 * 8500 + 1 * 120000);
  assert.equal(r.value.discount, 0);
  assert.equal(r.value.total, 5 * 8500 + 1 * 120000);
});

test('createInvoice accepts and stores discountPercent', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 10);
});

test('createInvoice accepts decimal discountPercent', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 12.5 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 12.5);
});

test('createInvoice accepts 0 and 100 discountPercent', () => {
  const r0 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
  });
  const r100 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 100 }],
  });
  assert.equal(r0.ok, true);
  assert.equal(r0.value.lines[0].discountPercent, 0);
  assert.equal(r100.ok, true);
  assert.equal(r100.value.lines[0].discountPercent, 100);
});

test('createInvoice rejects invalid discountPercent', () => {
  const cases = [
    { discountPercent: -1 },
    { discountPercent: 101 },
    { discountPercent: 'not a number' },
    { discountPercent: true },
  ];
  for (const line of cases) {
    const r = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 5, ...line }],
    });
    assert.deepEqual(r, { ok: false, error: 'DISCOUNT_INVALID' }, `should reject discountPercent=${line.discountPercent}`);
  }
});

test('createInvoice omits discountPercent if not provided', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  assert.ok(!('discountPercent' in r.value.lines[0]));
});

test('addLine adds a new line to an invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  });
  assert.equal(invoice.ok, true);
  const r = addLine(invoice.value, { sku: 'LOGO-PACK', qty: 1 });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 2);
  assert.equal(r.value.lines[1].sku, 'LOGO-PACK');
  assert.equal(r.value.lines[1].name, 'Logo package');
  assert.equal(r.value.lines[1].qty, 1);
});

test('addLine increments qty if SKU already exists', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  });
  assert.equal(invoice.ok, true);
  const r = addLine(invoice.value, { sku: 'DES-HOUR', qty: 2 });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 1);
  assert.equal(r.value.lines[0].qty, 5);
  assert.equal(r.value.lines[0].name, 'Design work (hour)');
});

test('addLine enriches new lines with product data', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(invoice.ok, true);
  const r = addLine(invoice.value, { sku: 'ICON-SET', qty: 2 });
  assert.equal(r.ok, true);
  const line = r.value.lines.find((l) => l.sku === 'ICON-SET');
  assert.equal(line.name, 'Icon set (24 icons)');
  assert.equal(line.unitPrice, 980);
  assert.equal(line.vatRate, 21);
});

test('addLine validates qty is a positive integer', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(invoice.ok, true);
  const cases = [0, -1, 1.5, '5', null];
  for (const qty of cases) {
    const r = addLine(invoice.value, { sku: 'LOGO-PACK', qty });
    assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' }, `should reject qty=${qty}`);
  }
});

test('addLine rejects unknown SKU', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(invoice.ok, true);
  const r = addLine(invoice.value, { sku: 'NOPE', qty: 1 });
  assert.deepEqual(r, { ok: false, error: 'UNKNOWN_SKU' });
});

test('addLine rejects non-draft invoices', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'sent',
    lines: [{ sku: 'DES-HOUR', qty: 1, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
  };
  const r = addLine(invoice, { sku: 'LOGO-PACK', qty: 1 });
  assert.deepEqual(r, { ok: false, error: 'NOT_DRAFT' });
});

test('addLine rejects null/invalid invoice', () => {
  const r = addLine(null, { sku: 'DES-HOUR', qty: 1 });
  assert.deepEqual(r, { ok: false, error: 'NOT_DRAFT' });
});

test('addLine does not mutate the original invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  });
  assert.equal(invoice.ok, true);
  const original = JSON.parse(JSON.stringify(invoice.value));
  addLine(invoice.value, { sku: 'LOGO-PACK', qty: 1 });
  assert.deepEqual(invoice.value, original);
});

test('addLine accepts and stores discountPercent', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  });
  assert.equal(invoice.ok, true);
  const r = addLine(invoice.value, { sku: 'LOGO-PACK', qty: 1, discountPercent: 20 });
  assert.equal(r.ok, true);
  const line = r.value.lines.find((l) => l.sku === 'LOGO-PACK');
  assert.equal(line.discountPercent, 20);
});

test('addLine rejects invalid discountPercent', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(invoice.ok, true);
  const cases = [-1, 101, 'not a number', true];
  for (const discountPercent of cases) {
    const r = addLine(invoice.value, { sku: 'LOGO-PACK', qty: 1, discountPercent });
    assert.deepEqual(r, { ok: false, error: 'DISCOUNT_INVALID' }, `should reject discountPercent=${discountPercent}`);
  }
});

test('removeLine removes a line from an invoice', () => {
